// Some portions generated by Co-Pilot
import { describe, it, expect, vi } from "vitest";
import { render } from "@testing-library/react";
import Calendar from "../index";

vi.mock("next-intl", async () => {
  const actual = await vi.importActual<typeof import("next-intl")>("next-intl");
  const messages = (await import("@/../locales/en.json")).default;
  return {
    ...actual,
    useTranslations: (namespace: "ModernPages.events") =>
      actual.createTranslator({ locale: "en", messages, namespace }),
  };
});

describe("Calendar", () => {
  it("renders correctly", () => {
    const { container } = render(<Calendar />);
    expect(container).toBeTruthy();
  });

  it("matches snapshot", () => {
    const { container } = render(<Calendar />);
    expect(container.firstChild).toMatchSnapshot();
  });

  it("displays the calendar title", () => {
    const { container } = render(<Calendar />);
    const heading = container.querySelector("h2");
    expect(heading).toHaveTextContent("Adoptium community calendar");
  });

  it("renders view calendar link with correct href", () => {
    const { container } = render(<Calendar />);
    const viewCalendarLink = container.querySelector(
      'a[href*="calendar.google.com/calendar/embed"]',
    );
    expect(viewCalendarLink).toHaveAttribute(
      "href",
      "https://calendar.google.com/calendar/embed?src=c_uannoums5ho0olhjk3ulecdkbc%40group.calendar.google.com",
    );
    expect(viewCalendarLink).toHaveAttribute("target", "_blank");
    expect(viewCalendarLink).toHaveAttribute("rel", "noopener noreferrer");
    expect(viewCalendarLink).toHaveTextContent("View calendar");
  });

  it("renders iCal subscription link with correct href", () => {
    const { container } = render(<Calendar />);
    const iCalLink = container.querySelector(
      'a[href*="calendar.google.com/calendar/ical"]',
    );
    expect(iCalLink).toHaveAttribute(
      "href",
      "https://calendar.google.com/calendar/ical/c_uannoums5ho0olhjk3ulecdkbc%40group.calendar.google.com/public/basic.ics",
    );
    expect(iCalLink).toHaveTextContent("Subscribe to iCal");
  });

  it("displays calendar description text", () => {
    const { container } = render(<Calendar />);
    const description = container.querySelector("p.text-grey");
    expect(description).toHaveTextContent(
      /Stay up to date with community meetings/,
    );
  });
});
